import{_ as i,o as a,c as t,ag as o}from"./chunks/framework.QOeHXaRf.js";const u=JSON.parse('{"title":"Application Configuration","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"developers/app-config.md","filePath":"developers/app-config.md"}'),n={name:"developers/app-config.md"};function s(l,e,r,c,p,d){return a(),t("div",null,e[0]||(e[0]=[o('<h1 id="application-configuration" tabindex="-1">Application Configuration <a class="header-anchor" href="#application-configuration" aria-label="Permalink to &quot;Application Configuration&quot;">​</a></h1><h2 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h2><p>GeoNetwork UI provides a standard way of configuring applications using the <a href="https://github.com/geonetwork/geonetwork-ui/tree/main/conf/default.toml" target="_blank" rel="noreferrer">default.toml</a> file.</p><p>This file can be used to:</p><ul><li>customize the URL used to reach the GeoNetwork 4 API</li><li>indicate an optional proxy path to the application</li><li>indicate a metadata language to be used when searching</li><li>customize the theme used in the application (colors, fonts...)</li><li>define custom translations for the different languages</li><li>customize filters for the search page</li></ul><p>Please refer to <a href="./../guide/configure.html">the configuration guide</a> as well as embedded comments in the file for more information.</p><h2 id="the-util-app-config-library" tabindex="-1">The <code>util/app-config</code> library <a class="header-anchor" href="#the-util-app-config-library" aria-label="Permalink to &quot;The `util/app-config` library&quot;">​</a></h2><p>This library is the one which should be used when parsing a configuration file. Using a configuration file is not mandatory, each application can decide whether this is relevant.</p><p>Only applications should rely on the <code>util/app-config</code> library! The other libraries should never assume that an application config is present, as this can very often not be the case (e.g. for web components).</p><h2 id="custom-loading" tabindex="-1">Custom loading <a class="header-anchor" href="#custom-loading" aria-label="Permalink to &quot;Custom loading&quot;">​</a></h2><p>By default, <code>loadAppConfig()</code> loads every section and requires the <code>[global]</code> and <code>[theme]</code> sections. Applications that only need part of the configuration (e.g. custom applications built with the <code>geonetwork-ui</code> NPM package) can pass the list of sections to load as second argument:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { loadAppConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@geonetwork-ui/util/app-config&#39;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">loadAppConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;theme&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;translations&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])</span></span></code></pre></div><p>Sections which are not loaded are considered absent: <code>getGlobalConfig()</code> and <code>getThemeConfig()</code> will throw, <code>getCustomTranslations()</code> returns an empty object, <code>getMetadataQualityConfig()</code> returns its default and the other getters return <code>null</code>.</p><p>An application which needs a section with different keys can implement its own <code>parse*Config</code> and <code>get*Config</code> functions. The custom parser can use existing logic like <code>parseConfigSection()</code> from the gn-ui utils. The app&#39;s <code>load*AppConfig</code> function can then use these custom parsers and keep the result in its own state. Since <code>loadAppConfig()</code> resolves with the parsed configuration file, the custom sections can be read from it without fetching the file again. An example for this could be a <code>[global]</code> section without the <code>geonetwork4_api_url</code> key, which is required in gn-ui&#39;s default <code>GlobalConfig</code>.</p>',14)]))}const g=i(n,[["render",s]]);export{u as __pageData,g as default};
